#!/usr/bin/env node
/* eslint-disable @typescript-eslint/no-require-imports */
'use strict';

const { execFileSync } = require('child_process');
const fs = require('fs');

function getArg(name) {
  const idx = process.argv.indexOf(name);
  return idx === -1 ? null : (process.argv[idx + 1] ?? '');
}

function getFlag(name) {
  return process.argv.includes(name);
}

function gh(args) {
  return execFileSync('gh', args, {
    encoding: 'utf8',
    stdio: ['ignore', 'pipe', 'pipe'],
  });
}

function appendOutput(outputPath, key, value) {
  const delimiter = `EOF-${Date.now()}-${Math.random().toString(16).slice(2)}`;
  fs.appendFileSync(
    outputPath,
    `${key}<<${delimiter}\n${String(value ?? '')}\n${delimiter}\n`,
  );
}

/**
 * Query recent completed runs for a workflow by display name.
 * Returns array of { conclusion, number, createdAt } newest-first,
 * matching the real `gh run list --json` field names.
 */
function queryWorkflowRuns(repo, workflowName, lookbackHours) {
  const since = new Date(
    Date.now() - lookbackHours * 60 * 60 * 1000,
  ).toISOString();
  try {
    const output = gh([
      'run', 'list', '--repo', repo, '--workflow', workflowName,
      '--status', 'completed', '--created', `${since}..`,
      '--limit', '50', '--json', 'conclusion,number,createdAt',
    ]);
    return JSON.parse(output.trim());
  } catch {
    return [];
  }
}

/**
 * Detect flaky pattern: same workflow has both failures and successes
 * with at least 2 transitions between states in the lookback window.
 * A transition is a change from pass→fail or fail→pass between
 * consecutive runs (newest-first chronological order).
 */
function isFlaky(runs) {
  if (!runs || runs.length < 3) return false;

  let failures = 0;
  let successes = 0;
  let transitions = 0;
  let prev = null;

  for (const r of runs) {
    const cur =
      r.conclusion === 'failure' || r.conclusion === 'timed_out'
        ? 'fail'
        : 'pass';
    if (cur === 'fail') failures++;
    else successes++;
    if (prev !== null && cur !== prev) transitions++;
    prev = cur;
  }

  return failures >= 2 && successes >= 1 && transitions >= 2;
}

/**
 * Find or create a flaky tracking issue for a workflow.
 * Returns { action, issue? }.
 */
function ensureFlakyIssue(repo, workflowName, evidence, dryRun) {
  const searchTitle = `Flaky workflow: ${workflowName}`;

  // Search for existing open flaky tracking issue
  try {
    const existing = JSON.parse(
      gh([
        'issue', 'list', '--repo', repo, '--state', 'open',
        '--search', `in:title "${searchTitle.replace(/"/g, '\\"')}"`,
        '--json', 'number,url', '--limit', '1',
      ]).trim(),
    );

    if (existing.length > 0) {
      if (!dryRun) {
        const ts = new Date().toISOString();
        gh([
          'issue', 'comment', String(existing[0].number), '--repo', repo,
          '--body',
          `## Flaky recurrence at ${ts}\n${evidence}`,
        ]);
      }
      return { action: 'commented', issue: existing[0] };
    }
  } catch (err) {
    console.error(`Search for existing flaky issue failed: ${err.message}`);
    // Fall through to create — search failure shouldn't block detection
  }

  if (dryRun) {
    return { action: 'dry-run-create' };
  }

  try {
    const output = gh([
      'issue', 'create', '--repo', repo,
      '--title', `[workflow-health] ${searchTitle}`,
      '--body',
        `## Flaky Workflow Detected\n\n${evidence}\n\n` +
        '---\nGenerated by workflow-health-optimize (WHO-E04).',
      '--label', 'auto-fix,needs-review',
    ]);
    const match = output.match(/\/issues\/(\d+)/);
    return {
      action: 'created',
      issue: {
        number: match ? match[1] : 'unknown',
        url: output.trim(),
      },
    };
  } catch (e) {
    return { action: 'error', error: e.message };
  }
}

/**
 * Build an evidence markdown block for a flaky workflow.
 */
function buildEvidence(workflowName, lookbackHours, runs) {
  const fails = runs.filter(
    r => r.conclusion === 'failure' || r.conclusion === 'timed_out',
  ).length;
  return [
    `**Workflow:** ${workflowName}`,
    `**Lookback:** ${lookbackHours} hours`,
    `**Pattern:** ${runs.length} run${runs.length === 1 ? '' : 's'}, ${fails} failure${fails === 1 ? '' : 's'}`,
    '**Recent runs:**',
    ...runs.slice(0, 8).map(
      r => `- ${r.conclusion} (run #${r.number}, ${r.createdAt})`,
    ),
  ].join('\n');
}

function run() {
  const repo = getArg('--repo') || process.env.GITHUB_REPOSITORY;
  const lookbackHours = parseInt(getArg('--lookback-hours') || '6', 10);
  const runsDataArg = getArg('--runs-data');
  const outputPath =
    getArg('--github-output') || process.env.GITHUB_OUTPUT;
  const dryRun = getFlag('--dry-run');

  // Parse current hour's runs data envelope
  let currentRuns = [];
  if (runsDataArg) {
    try {
      const envelope = JSON.parse(runsDataArg);
      currentRuns = envelope.runs || [];
    } catch {
      // Malformed JSON — nothing to detect
    }
  }

  // Collect workflow names with failures in the current hour
  const failedNames = new Set();
  for (const r of currentRuns) {
    if (r.status === 'failure' || r.status === 'timed_out') {
      if (r.name) failedNames.add(r.name);
    }
  }

  if (failedNames.size === 0) {
    if (outputPath) appendOutput(outputPath, 'flaky_workflows', '');
    if (outputPath) appendOutput(outputPath, 'flaky_detected', 'false');
    return;
  }

  const flakyWorkflows = [];
  const issueResults = [];

  for (const name of failedNames) {
    const recentRuns = queryWorkflowRuns(repo, name, lookbackHours);

    if (isFlaky(recentRuns)) {
      flakyWorkflows.push(name);

      const evidence = buildEvidence(name, lookbackHours, recentRuns);
      const result = ensureFlakyIssue(repo, name, evidence, dryRun);
      issueResults.push({ workflowName: name, ...result });
    }
  }

  if (outputPath) {
    appendOutput(
      outputPath,
      'flaky_detected',
      String(flakyWorkflows.length > 0),
    );
    appendOutput(
      outputPath,
      'flaky_workflows',
      flakyWorkflows.join(','),
    );
    appendOutput(
      outputPath,
      'flaky_issues',
      JSON.stringify(issueResults),
    );
  }
}

module.exports = { isFlaky, buildEvidence, ensureFlakyIssue, queryWorkflowRuns };

if (require.main === module) {
  run();
}
